import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Security & Sandboxing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1786221059000}'),r={name:"guide/security.md"};function n(o,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="security-sandboxing" tabindex="-1">Security &amp; Sandboxing <a class="header-anchor" href="#security-sandboxing" aria-label="Permalink to &quot;Security &amp; Sandboxing&quot;">​</a></h1><p>Chanakya MCP operates under a <strong>Zero-Trust, Zero-Network local model</strong>. It executes on your machine, interacts only with the codebase you choose to open, and exposes structured AST metadata exclusively over local <code>stdio</code>.</p><div class="custom-banner"><div class="custom-banner-icon">ðŸ”’</div><div class="custom-banner-content"><h4>100% Air-Gapped &amp; Private</h4><p>Zero telemetry, zero cloud dependencies, zero tracking. No OpenAI, Anthropic, or external embedding API keys are ever needed or contacted.</p></div></div><hr><h2 id="the-5-layers-of-security" tabindex="-1">The 5 Layers of Security <a class="header-anchor" href="#the-5-layers-of-security" aria-label="Permalink to &quot;The 5 Layers of Security&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Defense Layer</th><th style="text-align:left;">Mechanism</th><th style="text-align:left;">Security Objective</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Zero-Network Air-Gap</strong></td><td style="text-align:left;">Local Stdio JSON-RPC</td><td style="text-align:left;">No outbound HTTP/HTTPS requests or telemetry.</td></tr><tr><td style="text-align:left;"><strong>2. Path Sandboxing</strong></td><td style="text-align:left;">Lexical + Realpath Validation</td><td style="text-align:left;">Prevents path traversal out of the workspace root via <code>..</code> or symlinks.</td></tr><tr><td style="text-align:left;"><strong>3. ReDoS Worker Sandbox</strong></td><td style="text-align:left;">Worker Thread + Timeout Budget</td><td style="text-align:left;">Prevents regex backtracking CPU locks from crashing the server.</td></tr><tr><td style="text-align:left;"><strong>4. Parameterized SQL</strong></td><td style="text-align:left;">Prepared Statements + Wildcard Escaping</td><td style="text-align:left;">Eliminates SQL injection and unintended table-wide queries.</td></tr><tr><td style="text-align:left;"><strong>5. Stale-Content Guard</strong></td><td style="text-align:left;">2-Stage Hash + Timestamp Check</td><td style="text-align:left;">Rejects edits against stale files to avoid silent corruption.</td></tr></tbody></table><hr><h2 id="_1-path-containment-symlink-sandboxing" tabindex="-1">1. Path Containment &amp; Symlink Sandboxing <a class="header-anchor" href="#_1-path-containment-symlink-sandboxing" aria-label="Permalink to &quot;1. Path Containment &amp; Symlink Sandboxing&quot;">​</a></h2><p>Every relative or absolute path passed to an MCP tool is strictly validated:</p><ol><li><strong>Lexical Normalization:</strong> Verifies that the path does not contain parent traversal segments (<code>../</code>), drive letters on Windows, or root-relative paths.</li><li><strong>Canonical Realpath Check:</strong> Resolves symbolic links and junctions against the filesystem to guarantee that the target file does not reside outside the project directory.</li></ol><div class="warning custom-block"><p class="custom-block-title">SYMLINKS OUTSIDE PROJECT ROOT</p><p>If a symbolic link inside your repository points to <code>/etc/passwd</code> or an external directory, Codebrain detects the out-of-bounds target and rejects it immediately.</p></div><hr><h2 id="_2-worker-thread-redos-isolation" tabindex="-1">2. Worker Thread ReDoS Isolation <a class="header-anchor" href="#_2-worker-thread-redos-isolation" aria-label="Permalink to &quot;2. Worker Thread ReDoS Isolation&quot;">​</a></h2><p>User-supplied regular expressions in <code>search_code</code> are isolated in a worker thread with an enforced execution time budget (default: 500ms).</p><p>If a catastrophic backtracking pattern is encountered:</p><ul><li>The worker thread is terminated immediately.</li><li>The main MCP process remains healthy and responsive.</li><li>A fresh worker thread is spawned for subsequent queries.</li></ul><hr><h2 id="_3-parameterized-sqlite-escaped-queries" tabindex="-1">3. Parameterized SQLite &amp; Escaped Queries <a class="header-anchor" href="#_3-parameterized-sqlite-escaped-queries" aria-label="Permalink to &quot;3. Parameterized SQLite &amp; Escaped Queries&quot;">​</a></h2><p>All database queries are executed using parameterized prepared statements. Furthermore, special SQLite <code>LIKE</code> wildcards (<code>%</code>, <code>_</code>, <code>\\</code>) are automatically escaped in user search strings:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// A search for &quot;%&quot; searches for the literal character &quot;%&quot;,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// preventing accidental full-table scans.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> escaped_query</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> query.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">replace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">[%_</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">]</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">g</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$&amp;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><hr><h2 id="security-reporting" tabindex="-1">Security Reporting <a class="header-anchor" href="#security-reporting" aria-label="Permalink to &quot;Security Reporting&quot;">​</a></h2><p>If you discover a security vulnerability, please submit a private report via GitHub Security Advisories or open an issue on the repository. Security patches are prioritized and released promptly.</p>`,23)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
